// ================================================================
// WF-DHCP-WATCH — PHAT HIEN THIET BI MOI TU DHCP LOG PFSENSE
// ================================================================
// Sua loi:
// - DHCPDISCOVER thuong khong co hostname
// - Khong danh dau seen ngay tai dong dau tien
// - Gom tat ca log cua cung mot MAC
// - Lay hostname bo sung tu DHCPREQUEST / DHCPOFFER / DHCPACK
// ================================================================

// Doc tat ca item cua node, tranh truong hop Extract DHCP tra nhieu item
const readNodeText = (nodeName) => {
  try {
    return $(nodeName)
      .all()
      .map(item => String(item.json?.data || ''))
      .filter(Boolean)
      .join('\n');
  } catch (error) {
    return '';
  }
};

const dhcp = String($('Receive DHCP from WF-ANALYZER').first().json.dhcp_content || '');
const approvedTxt = readNodeText('Extract Approved');
const rejectedTxt = readNodeText('Extract Rejected');
const pendingTxt  = readNodeText('Extract Pending');

// ================================================================
// 1. Tao danh sach MAC da biet
// ================================================================

const normalizeMac = (mac) => String(mac || '').trim().toLowerCase();

const macOf = (line) => {
  const firstColumn = String(line || '').split(',')[0];
  return normalizeMac(firstColumn);
};

const known = new Set();

for (const txt of [approvedTxt, rejectedTxt, pendingTxt]) {
  for (const line of txt.split(/\r?\n/)) {
    const mac = macOf(line);

    if (mac) {
      known.add(mac);
    }
  }
}

// ================================================================
// 2. Doc log va gom thong tin theo tung MAC
// ================================================================

const RE_MAC = /([0-9a-f]{2}(?::[0-9a-f]{2}){5})/i;
const RE_EVENT = /\b(DHCPDISCOVER|DHCPREQUEST|DHCPOFFER|DHCPACK)\b/i;

const devices = new Map();
const lines = dhcp.split(/\r?\n/);

for (const raw of lines) {
  const line = raw.trim();

  if (!line) continue;

  const eventMatch = line.match(RE_EVENT);
  if (!eventMatch) continue;

  const event = eventMatch[1].toUpperCase();

  const macMatch = line.match(RE_MAC);
  if (!macMatch) continue;

  const mac = normalizeMac(macMatch[1]);

  if (!devices.has(mac)) {
    devices.set(mac, {
      mac,
      hostname: '',
      requestSeen: false,
      events: [],
      hostnameSource: '',
    });
  }

  const device = devices.get(mac);

  // Chi coi la thiet bi dang yeu cau vao mang neu co DISCOVER hoac REQUEST
  if (event === 'DHCPDISCOVER' || event === 'DHCPREQUEST') {
    device.requestSeen = true;
  }

  device.events.push(event);

  // Chi tim dau ngoac nam SAU dia chi MAC
  // Tranh lay nham cac noi dung ngoac khac trong log
  const macEndIndex = macMatch.index + macMatch[0].length;
  const textAfterMac = line.slice(macEndIndex);

  const hostnameMatch = textAfterMac.match(/^\s*\(([^)]+)\)/);

  if (hostnameMatch) {
    const hostname = hostnameMatch[1].trim();

    // Bo qua mot so gia tri khong phai hostname neu co
    if (
      hostname &&
      hostname.toLowerCase() !== 'found' &&
      hostname.toLowerCase() !== 'unknown'
    ) {
      device.hostname = hostname;
      device.hostnameSource = event;
    }
  }
}

// ================================================================
// 3. Chi lay MAC moi, chua tung approved/rejected/pending
// ================================================================

const newMacs = [];

for (const device of devices.values()) {
  if (!device.requestSeen) continue;
  if (known.has(device.mac)) continue;

  newMacs.push(device);
}

// ================================================================
// 4. Khong co MAC moi
// ================================================================

if (newMacs.length === 0) {
  return [
    {
      json: {
        no_new: true,
        scanned: lines.length,
        parsed_devices: Array.from(devices.values()),
      },
    },
  ];
}

// ================================================================
// 5. Tao payload Telegram
// ================================================================

return newMacs.map(device => {
  const hostname = device.hostname || '';

  const text =
    '⚠️ THIẾT BỊ MỚI YÊU CẦU VÀO MẠNG (VLAN2)\n' +
    'MAC: ' + device.mac + '\n' +
    'Hostname: ' + (hostname || ' ') + '\n\n' +
    'Chọn APPROVE để cấp IP, REJECT để không cấp IP.';

  return {
    json: {
      mac: device.mac,
      hostname,

      hostname_source: device.hostnameSource,
      dhcp_events: [...new Set(device.events)],

      pending_line:
        device.mac + ',' + hostname + '\n',

      telegram_text: text,

      reply_markup: {
        inline_keyboard: [
          [
            {
              text: '✅ APPROVE',
              callback_data: 'approve|' + device.mac,
            },
            {
              text: '⛔ REJECT',
              callback_data: 'reject|' + device.mac,
            },
          ],
        ],
      },
    },
  };
});

// ================================================================
// CREATE APPROVAL EVENT
// START cua kich ban APPROVE_MAC
// ================================================================

const now = Date.now();
const random = Math.random().toString(36).slice(2, 8).toUpperCase();

return items.map(item => {
  const mac = String(item.json.mac || '').trim().toLowerCase();

  return {
    json: {
      ...item.json,

      event_id: `APPROVE-${now}-${random}`,
      scenario: 'APPROVE_MAC',

      process_started_at_ms: now,
      process_started_at: new Date(now).toISOString(),

      status: 'pending_approval'
    }
  };
});

const item = $input.first();
const now = Date.now();
const random = Math.random().toString(36).slice(2, 8).toUpperCase();

const mac = String(item.json.mac || '').trim().toLowerCase();

const event = {
  schema_version: 1,
  event_id: `APPROVE-${now}-${random}`,
  scenario: 'APPROVE_MAC',

  mac,
  hostname: item.json.hostname || null,

  process_started_at_ms: now,
  process_started_at: new Date(now).toISOString(),

  status: 'pending_approval'
};

return [{
  json: {
    ...item.json,
    ...event,
    event_content: JSON.stringify(event) + '\n'
  }
}];
